import importlib.util
from pathlib import Path

# The script sits in the project root, outside the package.
spec = importlib.util.spec_from_file_location(
    "regen_release_deps", Path(__file__).parent.parent / "regen_release_deps.py"
)
rrd = importlib.util.module_from_spec(spec)
spec.loader.exec_module(rrd)


EXPORT = """\
# This file was autogenerated by uv via the following command:
#    uv export --frozen --no-dev --no-emit-project --no-hashes
textual==8.2.8
    # via pota-logger
rich==15.0.0
    # via textual
"""

PYPROJECT = """\
[project]
name = "pota-logger"
version = "2026.10.13.4+dev"
requires-python = ">=3.13"
dependencies = [
    "textual>=8.2.8",
]

[project.scripts]
pota-logger = "pota_logger.app:main"

[build-system]
requires = ["uv_build>=0.12.17,<0.13.0"]
build-backend = "uv_build"

[dependency-groups]
dev = [
    "pytest>=9.1.1",
]
"""


def fake_export(monkeypatch, output):
    """Make exported_pins read `output` instead of running uv."""

    class Done:
        stdout = output

    monkeypatch.setattr(rrd.subprocess, "run", lambda *a, **k: Done())


def test_exported_pins_drops_comments_and_sorts(monkeypatch):
    fake_export(monkeypatch, EXPORT)
    assert rrd.exported_pins(Path(".")) == ["rich==15.0.0", "textual==8.2.8"]


def test_normalized_ignores_case_and_spaces():
    assert rrd.normalized(["Textual == 8.2.8"]) == rrd.normalized(["textual==8.2.8"])


def test_dependencies_block_is_quoted_and_indented():
    assert rrd.dependencies_block(["a==1", "b==2"]) == (
        'dependencies = [\n    "a==1",\n    "b==2",\n]'
    )


def test_pins_match_compares_project_to_the_lock(monkeypatch):
    monkeypatch.setattr(rrd, "exported_pins", lambda cwd: ["textual==8.2.8"])
    monkeypatch.setattr(rrd, "project_dependencies", lambda cwd: ["textual==8.2.8"])
    assert rrd.pins_match(Path("."))
    monkeypatch.setattr(rrd, "project_dependencies", lambda cwd: ["textual>=8.2.8"])
    assert not rrd.pins_match(Path("."))


def test_write_dependencies_rewrites_only_the_project_block(monkeypatch, tmp_path):
    (tmp_path / "pyproject.toml").write_text(PYPROJECT)
    monkeypatch.setattr(rrd, "exported_pins", lambda cwd: ["rich==15.0.0", "textual==8.2.8"])
    locks = []
    monkeypatch.setattr(rrd.subprocess, "run", lambda *a, **k: locks.append(a))
    assert rrd.write_dependencies(tmp_path) is True
    text = (tmp_path / "pyproject.toml").read_text()
    assert 'dependencies = [\n    "rich==15.0.0",\n    "textual==8.2.8",\n]' in text
    # The dev group and build requires are left alone.
    assert 'dev = [\n    "pytest>=9.1.1",\n]' in text
    assert 'requires = ["uv_build>=0.12.17,<0.13.0"]' in text
    # It reconciles the lock afterward.
    assert locks and locks[0][0][:2] == ["uv", "lock"]


def test_write_dependencies_no_op_when_already_pinned(monkeypatch, tmp_path):
    (tmp_path / "pyproject.toml").write_text(PYPROJECT)
    monkeypatch.setattr(rrd, "exported_pins", lambda cwd: ["textual>=8.2.8"])
    ran = []
    monkeypatch.setattr(rrd.subprocess, "run", lambda *a, **k: ran.append(a))
    assert rrd.write_dependencies(tmp_path) is False
    assert ran == []  # no re-lock when nothing changed
